    interface Done {void accept(JSONObject result);}
    protected static JSONObject j(Object... pairs){JSONObject o=new JSONObject();try{for(int i=0;i<pairs.length;i+=2)o.put(String.valueOf(pairs[i]),pairs[i+1]);}catch(JSONException e){throw new IllegalArgumentException(e);}return o;}
    static LocalDate day(){return LocalDate.now(ZoneId.of("Asia/Jakarta"));}
    static JSONArray arr(JSONObject o,String key){JSONArray a=o.optJSONArray(key);return a==null?new JSONArray():a;}
    static JSONObject obj(JSONObject o,String key){JSONObject a=o.optJSONObject(key);return a==null?new JSONObject():a;}
    static String s(JSONObject o,String key){String v=o.optString(key,"");return "null".equals(v)?"":v;}
    static String rupiah(double n){return "Rp "+NumberFormat.getIntegerInstance(new Locale("id","ID")).format(n);}
    static String date(String raw){try{return LocalDate.parse(raw.substring(0,10)).format(DateTimeFormatter.ofPattern("d MMM yyyy",new Locale("id","ID")));}catch(Exception e){return raw;}}
    protected boolean preview(){return false;}
    @Override public void onCreate(Bundle saved){
        setTheme(R.style.AppTheme);super.onCreate(saved);vault=new Vault(this);api=new ParentApi(this);token=vault.get("token");
        if(saved!=null){screen=saved.getString("screen","home");studentId=saved.getString("student","");from=saved.getString("from",from);to=saved.getString("to",to);calendarYear=saved.getInt("year",calendarYear);}
        if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::back);
        if(preview()){startPreview();return;}
        if(token.isEmpty())login(false);else bootstrap();
    }
    protected void startPreview(){login(false);}
    protected void bootstrap(){
        String cached=vault.get("me");
        if(!cached.isEmpty()){try{students=arr(new JSONObject(cached),"students");selectValidStudent();dashboard();}catch(Exception ignored){}}
        if(students.length()==0){base("ATSkolla Parent",false);logo(body,104);title("Ruang orang tua", "Menyiapkan informasi ananda…");}
        call("me",j(),r->{students=arr(r,"students");try{vault.put("me",r.toString());}catch(Exception ignored){}selectValidStudent();dashboard();},null);
    }
    void selectValidStudent(){if(studentId.isEmpty())studentId=vault.get("student");boolean found=false;for(int i=0;i<students.length();i++)if(s(students.optJSONObject(i),"id").equals(studentId))found=true;if(!found)studentId=students.length()>0?s(students.optJSONObject(0),"id"):"";}
    JSONObject child(){for(int i=0;i<students.length();i++){JSONObject c=students.optJSONObject(i);if(c!=null&&studentId.equals(s(c,"id")))return c;}return new JSONObject();}
    void base(String name,boolean signedIn){
        shell=column(this);shell.setBackgroundColor(BG);shell.setOnApplyWindowInsetsListener((v,in)->{v.setPadding(in.getSystemWindowInsetLeft(),in.getSystemWindowInsetTop(),in.getSystemWindowInsetRight(),in.getSystemWindowInsetBottom());return in.consumeSystemWindowInsets();});setContentView(shell);shell.requestApplyInsets();
        LinearLayout top=row(this);top.setBackgroundColor(Color.WHITE);top.setPadding(dp(this,20),dp(this,10),dp(this,12),dp(this,10));
        ImageView mark=new ImageView(this);mark.setImageResource(R.drawable.atskolla_logo);mark.setContentDescription("Logo ATSkolla");top.addView(mark,new LinearLayout.LayoutParams(dp(this,36),dp(this,36)));
        LinearLayout names=column(this);names.setPadding(dp(this,12),0,0,0);names.addView(text(this,"ATSkolla",19,INK,true));names.addView(text(this,"PARENT • NATIVE",9,MUTED,true));top.addView(names,new LinearLayout.LayoutParams(0,-2,1));
        if(signedIn){iconButton(top,"bell","Pengumuman",()->navigate("info"));iconButton(top,"refresh","Muat ulang",()->load(true));}
        shell.addView(top);progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setIndeterminate(true);progress.setVisibility(View.GONE);shell.addView(progress,new LinearLayout.LayoutParams(-1,dp(this,2)));
        if(signedIn){studentBar=row(this);studentBar.setPadding(dp(this,20),dp(this,12),dp(this,16),dp(this,8));TextView label=text(this,s(child(),"name").isEmpty()?"Pilih siswa":s(child(),"name"),15,INK,true);studentBar.addView(label,new LinearLayout.LayoutParams(0,-2,1));TextView choose=text(this,"Ganti  ⌄",13,BLUE,true);choose.setPadding(dp(this,12),dp(this,12),dp(this,12),dp(this,12));choose.setOnClickListener(v->chooseStudent());studentBar.addView(choose);shell.addView(studentBar);}
        scroll=new ScrollView(this);scroll.setFillViewport(true);body=column(this);body.setPadding(dp(this,20),dp(this,12),dp(this,20),dp(this,24));scroll.addView(body,new ScrollView.LayoutParams(-1,-2));shell.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        heading=text(this,name,26,INK,true);body.addView(heading);gap(body,8);status=text(this,"",12,MUTED,false);body.addView(status);gap(body,12);
        if(signedIn){nav=row(this);nav.setBackgroundColor(Color.WHITE);String[] keys={"home","attendance","spp","schedule","more"};String[] labels={"Beranda","Absensi","SPP","Jadwal","Lainnya"};String[] icons={"home","check","wallet","calendar","grid"};for(int i=0;i<keys.length;i++){String key=keys[i];LinearLayout item=column(this);item.setGravity(Gravity.CENTER);item.setPadding(0,dp(this,10),0,dp(this,8));boolean active=key.equals(screen)||("more".equals(key)&&!Arrays.asList(keys).subList(0,4).contains(screen));int tint=active?BLUE:MUTED;item.addView(new Glyph(this,icons[i],tint),new LinearLayout.LayoutParams(dp(this,23),dp(this,23)));TextView t=text(this,labels[i],10,tint,active);item.addView(t);item.setContentDescription(labels[i]);item.setOnClickListener(v->navigate(key));nav.addView(item,new LinearLayout.LayoutParams(0,dp(this,64),1));}shell.addView(nav);}
    }
    void iconButton(LinearLayout row,String glyph,String label,Runnable action){FrameLayout target=new FrameLayout(this);Glyph icon=new Glyph(this,glyph,BLUE);FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(dp(this,22),dp(this,22),Gravity.CENTER);target.addView(icon,p);target.setContentDescription(label);target.setBackground(bg(this,Color.WHITE,24));target.setOnClickListener(v->action.run());row.addView(target,new LinearLayout.LayoutParams(dp(this,48),dp(this,48)));}
    void logo(LinearLayout parent,int size){ImageView image=new ImageView(this);image.setImageResource(R.drawable.atskolla_logo);image.setScaleType(ImageView.ScaleType.FIT_CENTER);image.setContentDescription("Logo ATSkolla");LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(dp(this,size),dp(this,size));p.gravity=Gravity.CENTER_HORIZONTAL;p.topMargin=dp(this,24);p.bottomMargin=dp(this,20);parent.addView(image,p);}
    void add(View v){body.addView(v,new LinearLayout.LayoutParams(-1,-2));gap(body,12);}
    void title(String t,String subtitle){add(text(this,t,24,INK,true));if(!subtitle.isEmpty())add(text(this,subtitle,15,MUTED,false));}
    void hint(String message){add(text(this,message,14,MUTED,false));}
    LinearLayout card(String title,String caption){LinearLayout c=Ui.card(this);c.addView(text(this,title,17,INK,true));if(!caption.isEmpty()){gap(c,6);c.addView(text(this,caption,13,MUTED,false));}add(c);return c;}
    void label(LinearLayout c,String text){gap(c,8);c.addView(Ui.text(this,text,14,INK,false));}
    void action(LinearLayout c,String label,boolean primary,Runnable run){gap(c,12);c.addView(button(this,label,primary,run),new LinearLayout.LayoutParams(-1,dp(this,50)));}
    void toast(String message){Toast.makeText(this,message,Toast.LENGTH_LONG).show();}
    void alert(String title,String message){new AlertDialog.Builder(this).setTitle(title).setMessage(message).setPositiveButton("Mengerti",null).show();}
    void error(Throwable e){preparingPayment=false;String m=e instanceof java.net.SocketTimeoutException?"Koneksi lambat. Data terakhir tetap tersedia; ketuk muat ulang untuk mencoba lagi.":(e.getMessage()==null?"Tidak dapat terhubung. Periksa internet Anda.":e.getMessage());if(status!=null)status.setText(m);toast(m);}
    void call(String action,JSONObject args,Done done,Button sending){
        String auth=token;if(sending!=null)sending.setEnabled(false);if(progress!=null)progress.setVisibility(View.VISIBLE);
        io.execute(()->{try{JSONObject result=api.call(action,args,auth);main.post(()->{if(isDestroyed()||!auth.equals(token))return;if(progress!=null)progress.setVisibility(View.GONE);if(sending!=null)sending.setEnabled(true);done.accept(result);});}
        catch(Exception ex){main.post(()->{if(isDestroyed()||!auth.equals(token))return;if(progress!=null)progress.setVisibility(View.GONE);if(sending!=null)sending.setEnabled(true);if(ex instanceof ParentApi.Failure&&((ParentApi.Failure)ex).unauthorized){clearSession();login(false);toast("Sesi berakhir. Silakan masuk kembali.");}else error(ex);});}});
    }
    void login(boolean phone){
        epoch++;base("",false);heading.setVisibility(View.GONE);status.setVisibility(View.GONE);logo(body,100);TextView hello=text(this,"Selamat datang kembali",25,INK,true);hello.setGravity(Gravity.CENTER);add(hello);TextView sub=text(this,"Satu ruang untuk mengikuti\nperjalanan belajar ananda.",15,MUTED,false);sub.setGravity(Gravity.CENTER);add(sub);gap(body,18);
        LinearLayout c=card("Masuk ke akun orang tua",phone?"Kode verifikasi dikirim melalui WhatsApp terdaftar.":"Gunakan 16 digit nomor kartu siswa.");
        EditText entry=input(this,phone?"Nomor WhatsApp":"Nomor kartu siswa",InputType.TYPE_CLASS_PHONE);if(!phone)entry.setFilters(new InputFilter[]{new InputFilter.LengthFilter(16)});gap(c,16);c.addView(entry);
        Button submit=button(this,phone?"Kirim kode WhatsApp":"Masuk sekarang",true,()->{});submit.setOnClickListener(v->{String value=entry.getText().toString().replaceAll("[^0-9]","");if((!phone&&value.length()!=16)||(phone&&value.length()<10)){entry.setError(phone?"Nomor belum lengkap":"Masukkan 16 digit kartu");return;}
            if(phone)call("request_otp",j("phone",value),r->{otpPhone=s(r,"phone");otp();},submit);
            else call("login_card",j("card_number",value),this::authenticated,submit);
        });gap(c,16);c.addView(submit,new LinearLayout.LayoutParams(-1,dp(this,52)));
        action(c,phone?"Masuk dengan kartu siswa":"Masuk dengan WhatsApp",false,()->login(!phone));
        hint("Dengan masuk, Anda mengakses data siswa yang terhubung dengan akun orang tua terdaftar.");
        add(button(this,"Privasi dan bantuan",false,this::privacy));
    }
    void otp(){base("Verifikasi WhatsApp",false);hint("Masukkan kode yang dikirim ke "+otpPhone+". Jangan bagikan kode Anda.");EditText code=input(this,"Kode OTP",InputType.TYPE_CLASS_NUMBER);code.setFilters(new InputFilter[]{new InputFilter.LengthFilter(6)});add(code);Button verify=button(this,"Verifikasi dan masuk",true,()->{});verify.setOnClickListener(v->call("verify_otp",j("phone",otpPhone,"otp",code.getText().toString()),this::authenticated,verify));add(verify);add(button(this,"Ganti nomor",false,()->login(true)));}
    void authenticated(JSONObject response){String t=s(response,"token");if(t.isEmpty()){alert("Gagal masuk","Server tidak mengembalikan sesi login.");return;}try{vault.clear();cache.clear();cacheTimes.clear();token=t;vault.put("token",token);students=new JSONArray();studentId="";screen="home";bootstrap();}catch(Exception e){token="";error(new IOException("Perangkat tidak dapat menyimpan sesi secara aman"));}}
    void chooseStudent(){if(students.length()==0){alert("Belum ada siswa","Hubungi admin sekolah untuk menghubungkan akun Anda.");return;}String[] labels=new String[students.length()];for(int i=0;i<labels.length;i++){JSONObject c=students.optJSONObject(i);labels[i]=s(c,"name")+" • "+s(c,"class");}new AlertDialog.Builder(this).setTitle("Pilih ananda").setItems(labels,(d,which)->{studentId=s(students.optJSONObject(which),"id");try{vault.put("student",studentId);}catch(Exception ignored){}pendingPayment="";navigate("home");}).show();}
    void dashboard(){if(students.length()==0){base("Akun orang tua",true);hint("Belum ada siswa terhubung. Hubungi sekolah.");add(button(this,"Keluar",false,this::logout));return;}load(false);}
    void navigate(String next){screen=next;visibleRows=40;load(false);}
    String screenTitle(){switch(screen){case "home":return "Kabar ananda hari ini";case "attendance":return "Kehadiran";case "spp":return "SPP & tagihan";case "schedule":return "Jadwal pelajaran";case "info":return "Pengumuman";case "leave":return "Pengajuan izin";case "contact":return "Wali kelas & sekolah";case "messages":return "Pesan wali kelas";case "grades":return "Nilai ananda";case "calendar":return "Kalender sekolah";case "card":return "Kartu pelajar";case "account":return "Akun & privasi";default:return "Semua layanan";}}
    void load(boolean force){
        int requestEpoch=++epoch;base(screenTitle(),true);
        if(studentId.isEmpty())return;
        if(screen.equals("more")){menu();return;}if(screen.equals("account")){account();return;}if(screen.equals("card")){studentCard();return;}
        if(screen.equals("home")){home(force,requestEpoch);return;}
        JSONObject args=j("student_id",studentId);String action=screen;
        switch(screen){case "attendance":action="attendance";args=j("student_id",studentId,"from",from,"to",to);break;case "info":action="announcements";break;case "leave":action="list_leaves";break;case "contact":action="homeroom";break;case "messages":action="list_messages";break;case "spp":action="spp_list";break;case "calendar":args=j("student_id",studentId,"year",calendarYear);break;}
        final String selectedScreen=screen;
        fetch(action,args,force,requestEpoch,(data,cached)->render(selectedScreen,data,cached));
    }
    interface Render {void accept(JSONObject result,boolean cached);}
    void fetch(String action,JSONObject args,boolean force,int generation,Render render){
        String key=action+":"+args.toString();JSONObject saved=cache.get(key);long age=System.currentTimeMillis()-cacheTimes.getOrDefault(key,0L);
        if(saved==null){String disk=vault.get(key);try{if(!disk.isEmpty()){JSONObject wrapped=new JSONObject(disk);saved=obj(wrapped,"data");age=System.currentTimeMillis()-wrapped.optLong("time");cache.put(key,saved);cacheTimes.put(key,wrapped.optLong("time"));}}catch(Exception ignored){}}
        if(saved!=null)render.accept(saved,true);else status.setText("Mengambil data terbaru…");
        // Messages mark teacher messages as read on the server and must always refresh.
        if(!force&&saved!=null&&age<60000&&!action.equals("list_messages")&&!action.equals("spp_list")){status.setText("Data tersimpan • ketuk muat ulang untuk memperbarui");return;}
        String auth=token;
        if(progress!=null)progress.setVisibility(View.VISIBLE);
        io.execute(()->{try{JSONObject result=api.call(action,args,auth);synchronized(vault){if(!auth.equals(token))return;long now=System.currentTimeMillis();cache.put(key,result);cacheTimes.put(key,now);vault.put(key,j("time",now,"data",result).toString());}main.post(()->{if(isDestroyed()||generation!=epoch||!auth.equals(token))return;progress.setVisibility(View.GONE);render.accept(result,false);});}
        catch(Exception ex){main.post(()->{if(isDestroyed()||generation!=epoch||!auth.equals(token))return;progress.setVisibility(View.GONE);if(ex instanceof ParentApi.Failure&&((ParentApi.Failure)ex).unauthorized){clearSession();login(false);}else{error(ex);if(body.getChildCount()<=4)add(button(this,"Coba lagi",true,()->load(true)));}});}});
    }
    void clearBody(){while(body.getChildCount()>4)body.removeViewAt(4);}
    void render(String name,JSONObject data,boolean cached){clearBody();status.setText(cached?"Data tersimpan • pemeriksaan terbaru sedang dilakukan":"Diperbarui "+LocalTime.now(ZoneId.of("Asia/Jakarta")).format(DateTimeFormatter.ofPattern("HH:mm"))+" WIB");switch(name){case "attendance":attendance(data);break;case "schedule":schedule(data);break;case "spp":invoices(data,cached);break;case "info":announcements(data);break;case "leave":leaves(data);break;case "contact":contact(data);break;case "messages":messages(data);break;case "grades":grades(data);break;case "calendar":calendar(data);break;}}
    void home(boolean force,int generation){
        JSONObject c=child();LinearLayout hero=Ui.card(this);GradientDrawable gradient=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{BLUE,0xFF394EB8});gradient.setCornerRadius(dp(this,24));hero.setBackground(gradient);hero.addView(text(this,"SELAMAT DATANG, ORANG TUA",10,0xFFD9E0FF,true));gap(hero,10);hero.addView(text(this,s(c,"name"),26,Color.WHITE,true));gap(hero,6);hero.addView(text(this,"Kelas "+s(c,"class")+"  •  "+s(c,"student_id"),14,0xFFE3E8FF,false));String school=s(obj(c,"schools"),"name");if(!school.isEmpty()){gap(hero,16);hero.addView(text(this,school,13,Color.WHITE,false));}add(hero);
        LinearLayout grid=row(this);String[] tabs={"leave","card","messages"};String[] labels={"Ajukan izin","Kartu pelajar","Pesan guru"};String[] icons={"check","card","message"};for(int i=0;i<tabs.length;i++){String next=tabs[i];LinearLayout item=Ui.card(this);Ui.pad(item,12);item.setGravity(Gravity.CENTER);item.addView(new Glyph(this,icons[i],BLUE),new LinearLayout.LayoutParams(dp(this,28),dp(this,28)));gap(item,10);TextView t=text(this,labels[i],11,INK,true);t.setGravity(Gravity.CENTER);item.addView(t);item.setOnClickListener(v->navigate(next));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(this,110),1);if(i<2)p.rightMargin=dp(this,10);grid.addView(item,p);}add(grid);
        LinearLayout attendanceCard=card("Kehadiran bulan ini","Menyiapkan ringkasan…");action(attendanceCard,"Lihat riwayat kehadiran",false,()->navigate("attendance"));
        LinearLayout announcementCard=card("Informasi sekolah","Memuat pengumuman terbaru…");action(announcementCard,"Semua pengumuman",false,()->navigate("info"));
        String id=studentId;
        fetch("attendance",j("student_id",id,"from",day().withDayOfMonth(1).toString(),"to",day().toString()),force,generation,(d,old)->{if(generation!=epoch)return;JSONArray a=arr(d,"attendance");Set<String> days=new HashSet<>();String latest="Belum ada catatan hari ini";for(int i=0;i<a.length();i++){JSONObject r=a.optJSONObject(i);if("hadir".equals(s(r,"status")))days.add(s(r,"date"));if(day().toString().equals(s(r,"date")))latest=s(r,"status")+" • "+s(r,"time");}((TextView)attendanceCard.getChildAt(2)).setText(days.size()+" hari hadir bulan ini\nHari ini: "+latest);status.setText(old?"Menampilkan data tersimpan":"Data terbaru • pemuatan per layar");});
        fetch("announcements",j("student_id",id),force,generation,(d,old)->{if(generation!=epoch)return;JSONArray a=arr(d,"announcements");((TextView)announcementCard.getChildAt(2)).setText(a.length()==0?"Belum ada pengumuman baru.":s(a.optJSONObject(0),"title"));});
        add(button(this,"SPP & tagihan ananda",true,()->navigate("spp")));
    }
    void menu(){String[][] items={{"info","Pengumuman","Informasi terbaru dari sekolah","bell"},{"leave","Izin & sakit","Pengajuan dan riwayat persetujuan","check"},{"contact","Wali kelas","Kontak guru dan informasi sekolah","card"},{"messages","Pesan","Percakapan dengan wali kelas","message"},{"grades","Nilai","Hasil belajar per semester","check"},{"calendar","Kalender sekolah","Libur dan kegiatan sekolah","calendar"},{"card","Kartu pelajar","Identitas, QR dan unduh kartu","card"},{"account","Akun & privasi","Identitas wali, privasi dan keluar","grid"}};for(String[] item:items){LinearLayout c=card(item[1],item[2]);String next=item[0];c.setOnClickListener(v->navigate(next));c.setContentDescription(item[1]+". "+item[2]);}}
    void account(){JSONObject c=child();LinearLayout details=card("Identitas wali murid",s(c,"parent_name"));label(details,s(c,"parent_phone"));label(details,"Siswa: "+s(c,"name"));label(details,"Kelas: "+s(c,"class"));LinearLayout security=card("Privasi perangkat","Sesi dan data tersimpan dienkripsi di perangkat. Data tidak dimasukkan ke pencadangan sistem.");action(security,"Hapus data tersimpan",false,()->new AlertDialog.Builder(this).setTitle("Hapus cache lokal?").setMessage("Anda tetap masuk. Data siswa akan diambil ulang dari sekolah.").setNegativeButton("Batal",null).setPositiveButton("Hapus",(d,w)->{String keep=token;vault.clear();cache.clear();cacheTimes.clear();try{vault.put("token",keep);}catch(Exception e){clearSession();}toast("Data tersimpan telah dihapus");}).show());action(security,"Bantuan / permintaan penghapusan akun",false,()->navigate("contact"));action(security,"Informasi layanan",false,this::privacy);action(security,"Keluar dari akun",false,this::logout);hint("ATSkolla Parent 2.0.0 • aplikasi Android native");}
    void privacy(){new AlertDialog.Builder(this).setTitle("Privasi ATSkolla Parent")
        .setMessage("Aplikasi ini ditujukan untuk orang tua/wali siswa.\n\nData yang diproses mencakup identitas siswa dan wali, kehadiran, jadwal, nilai, pesan, pengajuan izin beserta lampiran, serta informasi tagihan dan status pembayaran. Data digunakan untuk layanan sekolah dan komunikasi orang tua.\n\nData dikirim melalui HTTPS ke layanan ATSkolla. Pembayaran dilanjutkan pada layanan resmi penyedia pembayaran; aplikasi tidak meminta PIN atau sandi bank.\n\nSesi dan cache lokal dienkripsi dengan Android Keystore, tidak dicadangkan, dan dihapus saat keluar. Anda dapat menghapus cache melalui menu Akun. Aplikasi tidak meminta akses kontak, lokasi, atau penyimpanan perangkat secara menyeluruh.\n\nUntuk koreksi atau penghapusan akun/data, hubungi admin sekolah atau layanan ATSkolla. Data administrasi pembayaran dapat memiliki kewajiban retensi yang perlu dikonfirmasi kepada sekolah. Informasi kebijakan dan retensi lengkap harus disediakan pengelola sekolah/ATSkolla sebelum rilis publik.")
        .setPositiveButton("Mengerti",null).setNeutralButton("Hubungi ATSkolla",(dialog,which)->open("https://atskolla.com/kontak")).show();}
    void clearSession(){synchronized(vault){epoch++;token="";students=new JSONArray();studentId="";vault.clear();cache.clear();cacheTimes.clear();pendingPayment="";}}
    void logout(){new AlertDialog.Builder(this).setTitle("Keluar dari akun?").setMessage("Sesi dan cache siswa di perangkat ini akan dihapus.").setNegativeButton("Batal",null).setPositiveButton("Keluar",(d,w)->{String old=token;clearSession();login(false);io.execute(()->{try{api.call("logout",j(),old);}catch(Exception ignored){}});}).show();}
