    void invoices(JSONObject d,boolean cached){
        JSONArray a=arr(d,"invoices");if(a.length()==0){JSONArray pending=arr(d,"aktif"),paid=arr(d,"lunas");for(int i=0;i<pending.length();i++)a.put(pending.opt(i));for(int i=0;i<paid.length();i++)a.put(paid.opt(i));}
        double due=0;int unpaid=0;for(int i=0;i<a.length();i++){JSONObject r=a.optJSONObject(i);if(!"paid".equals(s(r,"status"))){due+=Math.max(0,r.optDouble("total_amount")-r.optDouble("installment_paid_amount"));unpaid++;}}
        LinearLayout summary=card(rupiah(due),unpaid+" tagihan belum lunas");if(cached)label(summary,"Data tersimpan. Pembayaran tersedia setelah pemeriksaan terbaru selesai.");
        JSONArray rows=a;list(rows,r->{boolean paid="paid".equals(s(r,"status"));String label=s(r,"period_label");if(label.isEmpty())label=s(r,"invoice_number");LinearLayout c=card(label,s(r,"invoice_number"));badge(c,s(r,"status"));label(c,rupiah(r.optDouble("total_amount")));label(c,"Jatuh tempo: "+date(s(r,"due_date")));double partial=r.optDouble("installment_paid_amount");if(partial>0)label(c,"Sudah dicicil: "+rupiah(partial));if(paid){label(c,"Dibayar "+date(s(r,"paid_at")));action(c,"Unduh bukti pembayaran PDF",false,()->invoicePdf(r));if(s(r,"id").equals(pendingPayment)){pendingPayment="";toast("Pembayaran telah tervalidasi oleh sekolah");}}
            else {Button pay=button(this,"Bayar tagihan",true,()->payment(r,0));pay.setEnabled(!cached);gap(c,12);c.addView(pay,new LinearLayout.LayoutParams(-1,dp(this,50)));if(r.optBoolean("allow_installment")&&!"spp".equals(s(r,"bill_type")))action(c,"Cicilan & riwayat",false,()->installments(r));action(c,"Unduh rincian tagihan PDF",false,()->invoicePdf(r));}
        });
        if(!pendingPayment.isEmpty()&&!cached&&paymentChecks<8&&foreground){main.removeCallbacks(paymentPoll);main.postDelayed(paymentPoll,20000);}
    }
    final Runnable paymentPoll=()->{if(foreground&&screen.equals("spp")&&!pendingPayment.isEmpty()&&paymentChecks++<8)load(true);};
    void installments(JSONObject invoice){call("installment_list",j("student_id",studentId,"invoice_id",s(invoice,"id")),r->{epoch++;base("Cicilan tagihan",true);LinearLayout summary=card(s(invoice,"period_label"),s(invoice,"invoice_number"));label(summary,"Lunas: "+rupiah(r.optDouble("paid_amount")));label(summary,"Menunggu pembayaran: "+rupiah(r.optDouble("pending_amount")));label(summary,"Dapat dicicil: "+rupiah(r.optDouble("remaining")));if(r.optDouble("remaining")>0){EditText amount=input(this,"Nominal cicilan (Rp)",InputType.TYPE_CLASS_NUMBER);add(amount);Button create=button(this,"Pilih metode pembayaran",true,()->{try{long value=Long.parseLong(amount.getText().toString());if(value<1000||value>r.optDouble("remaining")){amount.setError("Masukkan nominal Rp1.000 hingga sisa tagihan");return;}payment(invoice,value);}catch(Exception e){amount.setError("Masukkan nominal cicilan");}});add(create);}list(arr(r,"installments"),row->{LinearLayout c=card(rupiah(row.optDouble("amount")),date(s(row,"created_at")));badge(c,s(row,"status"));if("pending".equals(s(row,"status"))&&!s(row,"mayar_payment_url").isEmpty())action(c,"Lanjutkan pembayaran",false,()->{pendingPayment=s(invoice,"id");paymentChecks=0;open(s(row,"mayar_payment_url"));});});},null);}
    void payment(JSONObject invoice,long amount){if(preparingPayment)return;preparingPayment=true;call("payment_config",j(),cfg->{preparingPayment=false;String[] channels={"qris","va","retail"};JSONObject fees=obj(cfg,"fees");double bill=amount>0?amount:Math.max(0,invoice.optDouble("total_amount")-invoice.optDouble("installment_paid_amount"));String[] choices={"QRIS","Virtual account / transfer bank","Retail / minimarket"};new AlertDialog.Builder(this).setTitle("Pilih metode pembayaran").setItems(choices,(dialog,index)->{String channel=channels[index];double estimate=channel.equals("qris")?Math.max(fees.optDouble("qris",3000),Math.round(bill*cfg.optDouble("qris_percent",0.01))):fees.optDouble(channel);new AlertDialog.Builder(this).setTitle(choices[index]).setMessage("Tagihan: "+rupiah(bill)+"\nPerkiraan biaya layanan: "+rupiah(estimate)+"\n\nBiaya akhir akan ditampilkan sebelum melanjutkan ke penyedia pembayaran.").setNegativeButton("Batal",null).setPositiveButton("Buat pembayaran",(d,w)->{if(preparingPayment)return;preparingPayment=true;JSONObject args=j("student_id",studentId,"invoice_id",s(invoice,"id"),"channel",channel);String action="spp_pay";if(amount>0){action="spp_pay_installment";try{args.put("amount",amount);}catch(Exception ignored){}}call(action,args,result->{preparingPayment=false;String url=s(result,"payment_url");if(url.isEmpty()){alert("Belum dapat membayar","Tautan pembayaran tidak tersedia.");return;}double actual=result.optDouble("total_charged");new AlertDialog.Builder(this).setTitle("Pembayaran siap").setMessage("Total: "+rupiah(actual)+"\nBiaya layanan: "+rupiah(result.optDouble("service_fee"))+"\n\nAnda akan melanjutkan ke halaman resmi pembayaran melalui browser. Status lunas hanya mengikuti konfirmasi server.").setNegativeButton("Nanti",null).setPositiveButton("Lanjut pembayaran",(confirm,which)->{pendingPayment=s(invoice,"id");paymentChecks=0;screen="spp";open(url);}).show();},null);}).show();}).show();},null);}
    void studentCard(){JSONObject c=child();LinearLayout card=Ui.card(this);card.setPadding(dp(this,24),dp(this,24),dp(this,24),dp(this,24));TextView sch=text(this,s(obj(c,"schools"),"name"),17,BLUE,true);sch.setGravity(Gravity.CENTER);card.addView(sch);logo(card,62);TextView name=text(this,s(c,"name"),23,INK,true);name.setGravity(Gravity.CENTER);card.addView(name);TextView identity=text(this,"Kelas "+s(c,"class")+" • "+s(c,"student_id"),14,MUTED,false);identity.setGravity(Gravity.CENTER);card.addView(identity);gap(card,18);String data=s(c,"qr_code");if(data.isEmpty())data=s(c,"student_id");if(data.isEmpty())data=s(c,"id");try{BitMatrix matrix=new MultiFormatWriter().encode(data,BarcodeFormat.QR_CODE,512,512);Bitmap qr=Bitmap.createBitmap(512,512,Bitmap.Config.ARGB_8888);int[] pixels=new int[512*512];for(int y=0;y<512;y++)for(int x=0;x<512;x++)pixels[y*512+x]=matrix.get(x,y)?INK:Color.WHITE;qr.setPixels(pixels,0,512,0,0,512,512);ImageView qrView=new ImageView(this);qrView.setImageBitmap(qr);qrView.setContentDescription("Kode QR identitas siswa");LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(dp(this,184),dp(this,184));p.gravity=Gravity.CENTER_HORIZONTAL;card.addView(qrView,p);}catch(Exception e){label(card,"Kode QR belum tersedia");}gap(card,16);String number=s(c,"card_number");TextView numberText=text(this,number.replaceAll("(.{4})(?!$)","$1 "),17,INK,true);numberText.setGravity(Gravity.CENTER);card.addView(numberText);add(card);add(button(this,"Salin nomor kartu",false,()->{android.content.ClipboardManager cm=(android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE);cm.setPrimaryClip(ClipData.newPlainText("Nomor kartu ATSkolla",number));toast("Nomor kartu disalin");}));add(button(this,"Simpan kartu pelajar PNG",true,()->{try{int w=card.getWidth(),h=card.getHeight();if(w==0||h==0)return;Bitmap bitmap=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);canvas.drawColor(Color.WHITE);card.draw(canvas);ByteArrayOutputStream bytes=new ByteArrayOutputStream();bitmap.compress(Bitmap.CompressFormat.PNG,100,bytes);bitmap.recycle();export(bytes.toByteArray(),"image/png","Kartu-ATSkolla.png");}catch(Exception e){error(e);}}));hint("Simpan kartu hanya pada perangkat tepercaya.");}
    void invoicePdf(JSONObject invoice){call("school_info",j("student_id",studentId),school->{try{PdfDocument pdf=new PdfDocument();PdfDocument.Page page=pdf.startPage(new PdfDocument.PageInfo.Builder(595,842,1).create());Canvas c=page.getCanvas();Paint p=new Paint(3);c.drawColor(Color.WHITE);p.setColor(BLUE);c.drawRect(0,0,595,12,p);p.setColor(INK);p.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));p.setTextSize(27);c.drawText("ATSkolla Parent",44,66,p);p.setTextSize(14);c.drawText("paid".equals(s(invoice,"status"))?"BUKTI PEMBAYARAN":"RINCIAN TAGIHAN",44,96,p);p.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));p.setTextSize(12);String[] lines={s(obj(school,"school"),"name"),s(obj(school,"school"),"address"),"", "Invoice: "+s(invoice,"invoice_number"),"Siswa: "+s(child(),"name"),"Kelas: "+s(child(),"class"),"Periode: "+s(invoice,"period_label"),"Jatuh tempo: "+date(s(invoice,"due_date")),"Status: "+s(invoice,"status"),"Dibayar: "+date(s(invoice,"paid_at")),"Metode: "+s(invoice,"payment_method"),"", "Pokok tagihan: "+rupiah(invoice.optDouble("amount")),"Denda: "+rupiah(invoice.optDouble("denda")),"Total tagihan: "+rupiah(invoice.optDouble("total_amount")),"Cicilan diterima: "+rupiah(invoice.optDouble("installment_paid_amount")),"", "Biaya layanan penyedia pembayaran dapat tercantum terpisah.","Status pada dokumen mengikuti data server ketika dokumen dibuat.","Dicetak "+date(day().toString())};int y=134;for(String line:lines){for(String part:wrap(line,p,505)){c.drawText(part,44,y,p);y+=19;}}pdf.finishPage(page);ByteArrayOutputStream out=new ByteArrayOutputStream();pdf.writeTo(out);pdf.close();export(out.toByteArray(),"application/pdf",s(invoice,"invoice_number").replaceAll("[^A-Za-z0-9-]","-")+".pdf");}catch(Exception e){error(e);}},null);}
    static List<String> wrap(String text,Paint p,int width){List<String> lines=new ArrayList<>();StringBuilder current=new StringBuilder();for(String word:text.split(" ")){if(p.measureText(current+" "+word)>width&&current.length()>0){lines.add(current.toString());current.setLength(0);}if(current.length()>0)current.append(' ');current.append(word);}lines.add(current.toString());return lines;}
    void export(byte[] data,String mime,String filename){pendingDocument=data;Intent save=new Intent(Intent.ACTION_CREATE_DOCUMENT);save.addCategory(Intent.CATEGORY_OPENABLE);save.setType(mime);save.putExtra(Intent.EXTRA_TITLE,filename);startActivityForResult(save,700);}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null){if(request==700)pendingDocument=null;return;}Uri uri=data.getData();if(request==700&&pendingDocument!=null){byte[] bytes=pendingDocument;pendingDocument=null;io.execute(()->{try(OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException("Tidak dapat menyimpan berkas");out.write(bytes);main.post(()->toast("Berkas berhasil disimpan"));}catch(Exception e){main.post(()->error(e));}});}else if(request==701){final int generation=epoch;final String auth=token;final String mime=getContentResolver().getType(uri);if(!Arrays.asList("image/jpeg","image/png","image/webp","application/pdf").contains(mime)){toast("Pilih JPG, PNG, WebP atau PDF");return;}if(attachmentLabel!=null)attachmentLabel.setText("Mengunggah lampiran…");io.execute(()->{try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Berkas tidak dapat dibuka");ByteArrayOutputStream buffer=new ByteArrayOutputStream();byte[] part=new byte[8192];int n;while((n=in.read(part))!=-1){if(buffer.size()+n>5*1024*1024)throw new IOException("Lampiran maksimal 5 MB");buffer.write(part,0,n);}String ext=mime.equals("application/pdf")?".pdf":mime.equals("image/png")?".png":mime.equals("image/webp")?".webp":".jpg";String url=api.upload(buffer.toByteArray(),mime,ext,auth);main.post(()->{if(generation!=epoch||!auth.equals(token))return;attachment=url;if(attachmentLabel!=null)attachmentLabel.setText("Lampiran berhasil diunggah");});}catch(Exception e){main.post(()->{if(generation==epoch){if(attachmentLabel!=null)attachmentLabel.setText("Lampiran belum terunggah");error(e);}});}});}}
    void open(String url){try{Uri uri=Uri.parse(url);if(!Arrays.asList("https","tel","mailto").contains(uri.getScheme())){toast("Tautan tidak didukung");return;}startActivity(new Intent(Intent.ACTION_VIEW,uri).addCategory(Intent.CATEGORY_BROWSABLE));}catch(ActivityNotFoundException e){toast("Aplikasi untuk membuka tautan belum tersedia");}}
    void back(){if(!token.isEmpty()&&!screen.equals("home")){navigate("home");return;}finish();}
    // API 33+ is handled by the registered native OnBackInvokedCallback; this override is only for API 26–32.
    @android.annotation.SuppressLint("GestureBackNavigation")
    @Override public void onBackPressed(){back();}
    @Override protected void onResume(){super.onResume();foreground=true;if(!pendingPayment.isEmpty()&&!token.isEmpty()){screen="spp";paymentChecks=0;load(true);}}
    @Override protected void onPause(){foreground=false;main.removeCallbacks(paymentPoll);super.onPause();}
    @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putString("screen",screen);state.putString("student",studentId);state.putString("from",from);state.putString("to",to);state.putInt("year",calendarYear);}
    @Override protected void onDestroy(){main.removeCallbacksAndMessages(null);io.shutdownNow();super.onDestroy();}
